local function apply_full_stats(prototype_type, name, stats)
	local prototype = data.raw[prototype_type] and data.raw[prototype_type][name]
	if not prototype then
		return
	end
	local gun = prototype.gun and data.raw.gun[prototype.gun]
	local attack = gun and gun.attack_parameters or prototype.attack_parameters
	if not attack then
		return
	end
	for _, field in ipairs(entity_fields) do
		prototype[field] = nil
	end
	for field, value in pairs(stats.entity) do
		-- В старых артиллерийских прототипах эти числа были записаны строками.
		if type(value) == "string" and tonumber(value) then
			prototype[field] = tonumber(value)
		else
			prototype[field] = table.deepcopy(value)
		end
	end
	for _, field in ipairs(attack_fields) do
		attack[field] = nil
	end
	for field, value in pairs(stats.attack) do
		attack[field] = table.deepcopy(value)
	end
	-- Bob/Angel переименовали горючие жидкости; множители финальной 1.1 сохраняются.
	for index = #(attack.fluids or {}), 1, -1 do
		local fluid = attack.fluids[index]
		if not data.raw.fluid[fluid.type] then
			if data.raw.fluid["bob-" .. fluid.type] then
				fluid.type = "bob-" .. fluid.type
			elseif data.raw.fluid["angels-" .. fluid.type] then
				fluid.type = "angels-" .. fluid.type
			else
				table.remove(attack.fluids, index)
			end
		end
	end
end

return function()
	for _, record in ipairs(base_stats) do
		apply_full_stats(record[1], record[2], record[3])
	end
	-- W93 scattergun 1.1: первые два исследования давали основанию по +10%.
	if data.raw["ammo-turret"]["w93-scattergun-turret"] then
		for level = 1, 2 do
			local technology = data.raw.technology["physical-projectile-damage-" .. level]
			if technology then
				technology.effects = technology.effects or {}
				local present = false
				for _, effect in ipairs(technology.effects) do
					if effect.type == "turret-attack" and effect.turret_id == "w93-scattergun-turret" then
						effect.modifier = 0.1
						present = true
					end
				end
				if not present then
					table.insert(technology.effects, { type = "turret-attack", turret_id = "w93-scattergun-turret", modifier = 0.1 })
				end
			end
		end
	end
end
